function staticHtmlPlugin(): Plugin {
  return {
    name: 'static-html-generator',
    apply: 'build',
    closeBundle() {
      const distDir = join(process.cwd(), 'dist');
      const templatePath = join(distDir, 'index.html');

      if (!existsSync(templatePath)) {
        console.warn('Warning: dist/index.html not found for static HTML generation');
        return;
      }

      const templateHtml = readFileSync(templatePath, 'utf-8');
      console.log('\nGenerating static HTML files...\n');

      const replaceOrThrow = (source: string, search: string | RegExp, replacement: string, label: string): string => {
        const found = typeof search === 'string' ? source.includes(search) : source.match(search) !== null;
        if (!found) {
          throw new Error(`SSG replace failed: ${label}`);
        }
        return source.replace(search as any, replacement);
      };

      // Generate both Russian and Kyrgyz versions
      const allRoutes: { path: string; title: string; description: string; ogImage: string; content: string; locale: string }[] = [];
      
      // Add Russian routes
      for (const route of staticRoutes) {
        allRoutes.push({ ...route, locale: 'ru_RU' });
      }
      
      // Add Kyrgyz routes with translated content where available
      for (const route of staticRoutes) {
        const kyPath = route.path === '/' ? '/ky' : `/ky${route.path}`;
        const kyOverride = kyContentOverrides[route.path];
        
        allRoutes.push({
          path: kyPath,
          title: kyOverride?.title || route.title,
          description: kyOverride?.description || route.description,
          ogImage: route.ogImage,
          content: kyOverride?.content || route.content,
          locale: 'ky_KG'
        });
      }

      for (const route of allRoutes) {
        let html = templateHtml;

        // Изменить lang атрибут для кыргызских страниц
        if (route.locale === 'ky_KG') {
          html = replaceOrThrow(html, /<html lang="ru">/, '<html lang="ky">', 'html lang');
        }

        html = replaceOrThrow(html, /<title>.*?<\/title>/, `<title>${route.title}</title>`, 'title');
        html = replaceOrThrow(
          html,
          /<meta name="description" content=".*?".*?\/>/,
          `<meta name="description" content="${route.description}" />`,
          'meta description'
        );

        // Генерация hreflang тегов
        const langPath = route.path.startsWith('/ky') ? (route.path.slice(3) || '/') : route.path;
        const ruUrl = `https://calk.kg${langPath === '/' ? '' : langPath}`;
        const kyUrl = `https://calk.kg/ky${langPath === '/' ? '' : langPath}`;
        const canonicalUrl = `https://calk.kg${route.path === '/' ? '' : route.path}`;

        const hreflangTags = `
    <link rel="alternate" hreflang="ru" href="${ruUrl}" />
    <link rel="alternate" hreflang="ky" href="${kyUrl}" />
    <link rel="alternate" hreflang="x-default" href="${ruUrl}" />`;

        const ogTags = `
    <meta property="og:title" content="${route.title}" />
    <meta property="og:description" content="${route.description}" />
    <meta property="og:url" content="${canonicalUrl}" />
    <meta property="og:type" content="website" />
    <meta property="og:image" content="${route.ogImage}" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta property="og:locale" content="${route.locale}" />
    <meta property="og:site_name" content="Calk.KG" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${route.title}" />
    <meta name="twitter:description" content="${route.description}" />
    <meta name="twitter:image" content="${route.ogImage}" />
    <link rel="canonical" href="${canonicalUrl}" />${hreflangTags}`;

        const schemaLanguage = route.locale === 'ky_KG' ? 'ky' : 'ru';
        const basePath = langPath === '' ? '/' : langPath;
        const isHome = basePath === '/';
        const isCalculator = basePath.startsWith('/calculator/');

        const schemaData = isCalculator
          ? generateCalculatorSchema({
              url: canonicalUrl,
              title: route.title,
              description: route.description,
              calculatorName: route.title,
              category: 'Calculator',
              language: schemaLanguage
            })
          : isHome
            ? generateWebSiteSchema({
                url: canonicalUrl,
                title: route.title,
                description: route.description,
                language: schemaLanguage
              })
            : generateWebPageSchema({
                url: canonicalUrl,
                title: route.title,
                description: route.description,
                language: schemaLanguage
              });

        const organizationSchema = generateOrganizationSchema({
          name: "Calk.KG",
          url: "https://calk.kg",
          logo: "https://calk.kg/calculator-logo.svg",
          description: route.description,
          contactEmail: "info@calk.kg",
          address: {
            addressCountry: "KG",
            addressRegion: "Чуйская область",
            addressLocality: "Бишкек"
          }
        });

        const jsonLdSchemas = isHome ? [schemaData, organizationSchema] : [schemaData];
        const jsonLdTag = `
    <script type="application/ld+json">
${createJsonLdScript(jsonLdSchemas.length === 1 ? jsonLdSchemas[0] : jsonLdSchemas)}
    </script>`;

        html = replaceOrThrow(html, '</head>', `${ogTags}${jsonLdTag}\n  </head>`, 'head tags');

        // Футер на соответствующем языке
        const footerContent = route.locale === 'ky_KG' 
          ? `<p><a href="/ky">Calk.KG</a> - Кыргызстандын акысыз онлайн калькуляторлору</p>
             <nav>
               <a href="/ky/about">Биз жөнүндө</a> |
               <a href="/ky/sitemap">Сайт картасы</a> |
               <a href="/ky/privacy-policy">Купуялык</a>
             </nav>`
          : `<p><a href="/">Calk.KG</a> - Бесплатные онлайн калькуляторы Кыргызстана</p>
             <nav>
               <a href="/about">О проекте</a> |
               <a href="/sitemap">Карта сайта</a> |
               <a href="/privacy-policy">Конфиденциальность</a>
             </nav>`;

        const staticContent = `
      <main id="static-content" data-ssg-static="true" style="max-width: 800px; margin: 0 auto; padding: 20px; font-family: system-ui, sans-serif;">
        ${route.content}
        <footer style="margin-top: 40px; padding-top: 20px; border-top: 1px solid #eee;">
          ${footerContent}
        </footer>
      </main>`;

        // Inject static content directly into root so crawlers see it in main DOM.
        html = replaceOrThrow(
          html,
          /<div id="root">(?:<div class="loading-spinner"><\/div>)?<\/div>/,
          `<div id="root">${staticContent}</div>`,
          'root content'
        );

        if (route.path === '/') {
          writeFileSync(join(distDir, 'index.html'), html);
          console.log(`  / -> dist/index.html`);
        } else {
          const dirPath = join(distDir, route.path);
          if (!existsSync(dirPath)) {
            mkdirSync(dirPath, { recursive: true });
          }
          writeFileSync(join(dirPath, 'index.html'), html);
          console.log(`  ${route.path} -> dist${route.path}/index.html`);
        }
      }

      const sitemapPath = join(distDir, 'sitemap.xml');
      if (existsSync(sitemapPath)) {
        const today = new Date().toISOString().slice(0, 10);
        const sitemap = readFileSync(sitemapPath, 'utf-8');
        const refreshedSitemap = sitemap.replace(/<lastmod>\d{4}-\d{2}-\d{2}<\/lastmod>/g, `<lastmod>${today}</lastmod>`);
        writeFileSync(sitemapPath, refreshedSitemap);
        console.log(`\n  Updated sitemap lastmod -> ${today}`);
      }

      console.log(`\nGenerated ${allRoutes.length} static HTML files (${staticRoutes.length} RU + ${staticRoutes.length} KY).`);
    }
  };
}

export default defineConfig({
  plugins: [
    react(),
    staticHtmlPlugin(),
    // Gzip compression (fallback)
    compression({
      algorithm: 'gzip',
      ext: '.gz',
      threshold: 1024, // Only compress files > 1KB
    }),
    // Brotli compression (preferred, better ratio)
    compression({
      algorithm: 'brotliCompress',
      ext: '.br',
      threshold: 1024,
    }),
  ],
  optimizeDeps: {
    exclude: ['lucide-react'],
  },
  build: {
    // Enable minification
    minify: 'terser',
    terserOptions: {
      compress: {
        drop_console: true, // Remove console.log in production
        drop_debugger: true,
      },
    },
    // Enable CSS code splitting
    cssCodeSplit: true,
    // Reduce chunk size
    rollupOptions: {
      output: {
        manualChunks(id) {
          if (id.includes('react-dom') || id.includes('react-router-dom')) {
            return 'react-vendor';
          }
          if (id.includes('react-helmet-async')) {
            return 'helmet';
          }
          if (id.includes('lucide-react')) {
            return 'icons';
          }
          if (id.includes('i18n/translations-ru')) {
            return 'translations-ru';
          }
          // translations-ky is NOT matched here — Vite handles it
          // as a dynamic import chunk automatically via src/i18n/index.ts
          if (id.includes('/data/') && (
            id.includes('trafficFines') ||
            id.includes('transferServices') ||
            id.includes('constructionData') ||
            id.includes('cropData') ||
            id.includes('fuelData') ||
            id.includes('rentalData') ||
            id.includes('scholarshipData') ||
            id.includes('sickLeaveData') ||
            id.includes('mobileTariffs')
          )) {
            return 'calculator-data';
          }
        },
        // Optimize chunk file names for caching
        chunkFileNames: 'assets/[name]-[hash].js',
        entryFileNames: 'assets/[name]-[hash].js',
        assetFileNames: 'assets/[name]-[hash].[ext]',
      },
    },
    chunkSizeWarningLimit: 1000,
    // Enable source maps for debugging (optional)
    sourcemap: false,
  },
});
